namespace InventoryApp.Services;

public record EquipmentItem(
    int Id,
    string Name,
    string Location,
    DateTime LastInspected);

public interface IEquipmentService
{
    Task<List<EquipmentItem>> GetEquipmentAsync();
}

public class EquipmentService : IEquipmentService
{
    public async Task<List<EquipmentItem>> GetEquipmentAsync()
    {
        // Simulate a slow data source
        await Task.Delay(500);

        return new List<EquipmentItem>
        {
            new(1, "Forklift A",        "Warehouse 1", new DateTime(2026, 5, 10)),
            new(2, "Conveyor Belt B",    "Warehouse 2", new DateTime(2026, 4, 22)),
            new(3, "Pallet Jack C",      "Dock 3",      new DateTime(2026, 3, 15)),
            new(4, "Crane D",            "Yard",        new DateTime(2026, 5, 28)),
            new(5, "Compressor E",       "Maintenance", new DateTime(2026, 1, 8)),
            new(6, "Welding Rig F",      "Shop Floor",  new DateTime(2025, 12, 19)),
            new(7, "Drill Press G",      "Shop Floor",  new DateTime(2026, 2, 3)),
        };
    }
}

@page "/inventory"
@rendermode InteractiveServer
@attribute [StreamRendering]
@using InventoryApp.Services
@inject IEquipmentService EquipmentService
@inject PersistentComponentState PersistentState
@implements IDisposable

<PageTitle>Inventory</PageTitle>

<h1>Equipment Inventory</h1>

@if (_items is null)
{
    <p><em>Loading inventory...</em></p>
}
else
{
    <table class="table">
        <thead>
            <tr>
                <th>Id</th>
                <th>Name</th>
                <th>Location</th>
                <th>Last Inspected</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var item in _items)
            {
                <tr>
                    <td>@item.Id</td>
                    <td>@item.Name</td>
                    <td>@item.Location</td>
                    <td>@item.LastInspected.ToShortDateString()</td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    private List<EquipmentItem>? _items;
    private PersistingComponentStateSubscription _subscription;

    protected override async Task OnInitializedAsync()
    {
        // During interactive init, reuse data persisted from the prerender.
        // This prevents a second call to the service.
        if (PersistentState.TryTakeFromJson<List<EquipmentItem>>(
                nameof(_items), out var restored))
        {
            _items = restored;
        }
        else
        {
            _items = await EquipmentService.GetEquipmentAsync();
        }

        // Register the data so it survives the prerender → interactive handoff.
        _subscription = PersistentState.RegisterOnPersisting(() =>
        {
            PersistentState.PersistAsJson(nameof(_items), _items);
            return Task.CompletedTask;
        });
    }

    public void Dispose() => _subscription.Dispose();
}

